/* ── HTML escape ── */
function _esc(s){ return (s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
/* ── JSON 데이터를 인라인 <script> 에 안전 임베드 ──
   JSON.stringify 는 '</script>' 를 그대로 두므로, 사용자가 라벨·문구에 '</script>' 같은 문자를 넣으면
   인라인 스크립트가 조기 종료되어 키오스크 JS 전체가 깨진다(흰 화면). '<' 를 < 로, 그리고 JS 문자열에서
   개행으로 취급되는 U+2028/U+2029 를 이스케이프해 방어한다. (2026-06-13 검증 중 발견·수정) */
function _J(o){var s=JSON.stringify(o).replace(/</g,"\\u003c");var A=String.fromCharCode(8232),B=String.fromCharCode(8233);return s.split(A).join("\\u2028").split(B).join("\\u2029");}

