/* ── 이미지 base64 캐시 (앱 로드 시 미리 압축) ── */
var _bmCache = null;
var _bmCacheIsKinder = null;
var _bgCache = null;

/* ── 호출음 (dingdong.mp3) base64 캐시 ── */
var _dingdongB64 = null;
function _loadDingdong(callback){
  if(_dingdongB64 !== null){ callback(_dingdongB64); return; }
  fetch('assets/sounds/dingdong.mp3')
    .then(function(r){ return r.blob(); })
    .then(function(blob){
      var reader = new FileReader();
      reader.onloadend = function(){
        /* reader.result = "data:audio/mpeg;base64,AAAA..." */
        _dingdongB64 = reader.result || '';
        callback(_dingdongB64);
      };
      reader.readAsDataURL(blob);
    })
    .catch(function(e){ console.warn('[KIOSK] dingdong.mp3 로드 실패:', e); _dingdongB64 = ''; callback(''); });
}

