/* ── 개별 이미지 Canvas 압축 ── */
function _compressOne(src, callback, keepPng){
  var img = new Image();
  img.onload = function(){
    var canvas = document.createElement('canvas');
    var maxW = 1280;
    var ratio = Math.min(maxW / img.width, 1);
    canvas.width = Math.round(img.width * ratio);
    canvas.height = Math.round(img.height * ratio);
    canvas.getContext('2d').drawImage(img, 0, 0, canvas.width, canvas.height);
    if(keepPng){
      callback(canvas.toDataURL('image/png'));
    } else {
      callback(canvas.toDataURL('image/jpeg', 0.65));
    }
  };
  img.onerror = function(){ console.warn('[KIOSK] 이미지 로드 실패:', src); callback(''); };
  img.src = src;
}

/* ── 바디맵 7종 압축 (캐시 히트 시 즉시 반환) ── */
function _compressAllBodymap(callback){
  var isKinder = ((S.settings||{}).schoolLevel === 'kindergarten');
  if(_bmCache && _bmCacheIsKinder === isKinder){ callback(_bmCache); return; }
  var paths = isKinder ? BM_IMAGE_PATHS_CHILD : BM_IMAGE_PATHS;
  var keys = Object.keys(paths);
  var result = {};
  var done = 0;
  keys.forEach(function(key){
    _compressOne(paths[key], function(b64){
      result[key] = b64;
      done++;
      if(done === keys.length){ _bmCache = result; _bmCacheIsKinder = isKinder; callback(result); }
    }, true);
  });
}

/* ── 배경 12장 압축 (캐시 히트 시 즉시 반환) ── */
function _compressAllBg(callback){
  if(_bgCache){ callback(_bgCache); return; }
  var total = BG_IMAGE_PATHS.length;
  if(!total){ _bgCache = []; callback([]); return; }
  var results = [];
  var done = 0;
  BG_IMAGE_PATHS.forEach(function(p, i){
    _compressOne(p, function(b64){
      results[i] = b64;
      done++;
      if(done === total){ _bgCache = results; callback(results); }
    });
  });
}

/* ── 앱 로드 시 백그라운드로 미리 압축 시작 ── */
setTimeout(function(){
  _compressAllBodymap(function(){ /* 바디맵 캐시 완료 */ });
  _compressAllBg(function(){ /* 배경 캐시 완료 */ });
}, 2000);

function _findSection(flow, id){
  return flow.sections.find(function(s){ return s.id === id; });
}

/* (템플릿 기반 빌드 제거됨 — 기본형/확장형 모두 buildKioskHtml()로 동적 생성) */

/* ══════════════════════════════════════════
   키오스크 HTML 다운로드 생성
   ══════════════════════════════════════════ */
export function downloadKioskHtml(getFlowFn){
  bus.emit('toast:show', {text: 'HTML 생성 중…'});
  const _kcBody = document.getElementById('_kcFlowBody');
  if(_kcBody) showLoading(_kcBody, '키오스크 HTML 생성 중…');

  /* 캐시된 이미지 사용 (앱 로드 시 미리 압축됨) + 호출음 로드 */
  _compressAllBodymap(function(bmMap){
    _compressAllBg(function(bgB64){
      _loadDingdong(function(dingdongB64){
        _buildAndDownload(bgB64, getFlowFn, bmMap, dingdongB64);
        if(_kcBody) hideLoading(_kcBody);
      });
    });
  });
}

