    + '<div class="bm-zone" data-bm-key="footBottom" style="flex:1"><img crossorigin="anonymous" src="' + (bmMap.footBottom || bmPaths.footBottom) + '">' + _kBmLrLabelsHtml('footBottom') + '<div class="bm-markers"><\/div><\/div><\/div>'
