      let guideT = _esc(sec.guideText || '');
      guideT = guideT.replace(/([①②③④⑤⑥⑦⑧⑨⑩])/g, '\n$1').replace(/(\d+)\.\s/g, '\n$1. ').replace(/\((\d+)\)/g, '\n($1)').replace(/^\n/, '');
