    +       '<div><div style="font-size:12.5px;font-weight:800;color:' + (ks.active?'var(--gs)':'var(--t1)') + '">' + (ks.active?'키오스크 활성':'키오스크 비활성') + '</div>'
    +       '<div style="font-size:10px;color:var(--t3)">' + (ks.active?'접속 대기 중 — 방문자가 키오스크를 사용할 수 있습니다':'활성화하면 QR 코드와 URL이 표시됩니다') + '</div></div>'
