    +   (ks.active ? '<div style="font-size:13.5px;font-weight:800;color:#dc2626;background:rgba(220,38,38,0.07);border:1px solid rgba(220,38,38,0.35);border-radius:10px;padding:12px 14px;margin-bottom:14px;text-align:center;line-height:1.5">⚠️ 위 QR 코드와 URL 링크는 외부로 절대 공유하지 마세요!</div>' : '')
