    + '#_kbzOverlay .kbz-head{padding:12px 20px;background:rgba(6,182,212,0.10);border-bottom:1px solid var(--bdr);display:flex;align-items:center;justify-content:space-between;gap:10px;flex-shrink:0;cursor:grab}'
    + '#_kbzOverlay .kbz-head .t{font-size:14px;font-weight:800;color:var(--t1);display:flex;align-items:center;gap:8px}'
    + '#_kbzOverlay .kbz-x{cursor:pointer;font-size:16px;color:var(--t3);padding:4px 10px;line-height:1;border-radius:8px}#_kbzOverlay .kbz-x:hover{background:var(--bg2);color:var(--t1)}'
    + '#_kbzOverlay .kbz-body{flex:1;display:flex;min-height:0}'
    + '#_kbzOverlay .kbz-stage{flex:1;min-width:0;background:var(--bg2);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;padding:20px;overflow:hidden}'
    + '#_kbzOverlay .kbz-wrap{flex:1;display:flex;align-items:center;justify-content:center;width:100%;min-height:0}'
    + '#_kbzOverlay .kbz-device{background:#0f172a;border-radius:22px;padding:12px;box-shadow:0 18px 50px rgba(0,0,0,0.4);transform-origin:center center;flex-shrink:0}'
    + '#_kbzOverlay #_kbzFrame{border:0;background:#000;border-radius:8px;display:block}'
    + '#_kbzOverlay .kbz-meta{font-size:12px;color:var(--t2);background:var(--card);padding:6px 14px;border-radius:999px;border:1px solid var(--bdr)}#_kbzOverlay .kbz-meta b{color:var(--cyan)}'
    + '#_kbzOverlay .kbz-div{width:1px;background:var(--bdr)}'
    + '#_kbzOverlay .kbz-side{width:286px;flex-shrink:0;background:var(--card);border-left:1px solid var(--bdr);padding:16px 16px 18px;overflow-y:auto}'
    + '#_kbzOverlay .kbz-side .st{font-size:13px;font-weight:800;margin-bottom:3px;color:var(--t1)}#_kbzOverlay .kbz-side .sd{font-size:11px;color:var(--t3);line-height:1.5;margin-bottom:14px}'
    + '#_kbzOverlay .kbz-tog{display:flex;gap:6px;margin-bottom:14px}#_kbzOverlay .kbz-tog button{flex:1;padding:8px;font-size:12px;font-weight:700;border:1.5px solid var(--bdr);background:var(--card);border-radius:8px;cursor:pointer;font-family:inherit;color:var(--t2)}#_kbzOverlay .kbz-tog button.on{border-color:var(--cyan);background:rgba(6,182,212,0.08);color:var(--cyan)}'
