    +     '<div style="font-size:10.5px;font-weight:600;color:var(--cyan);line-height:1.5;margin-bottom:14px">🖥️ 가로형(가로 디스플레이)으로 보면 보건실 이용 안내 등 별도 안내가 화면 왼쪽에 상시 표시됩니다.</div>'
    +     '<div class="kbz-tog kbz-ornt"><button data-o="landscape" class="'+(ORIENT==='portrait'?'':'on')+'">🖥️ 가로</button><button data-o="portrait" class="'+(ORIENT==='portrait'?'on':'')+'">📲 세로</button></div>'
    +     typeToggleHtml
    +     sideButtons
    +     '<div class="kbz-note">💡 휴대폰(갤럭시 S·노트, 아이폰)은 <b>세로형이 적절</b>합니다. 휴대폰을 고르면 자동으로 세로로 표시됩니다. 태블릿은 가로·세로 모두 적합합니다.</div>'
    +   '</div>'
    + '</div>'
    + '</div>';
  document.body.appendChild(ov);

  var frame=ov.querySelector('#_kbzFrame'), device=ov.querySelector('#_kbzDevice'), wrap=ov.querySelector('.kbz-wrap'), meta=ov.querySelector('#_kbzMeta'), cur=null;
  function loadSrc(){ frame.srcdoc = htmls[keyFor(ORIENT,TYPE)] || '<!doctype html><meta charset="utf-8"><body style="font-family:sans-serif;padding:20px;color:#64748b">미리보기를 생성하지 못했습니다.</body>'; }
  function dimsOf(b){ var lo=+b.dataset.lo, sh=+b.dataset.sh; return ORIENT==='portrait'?{w:sh,h:lo}:{w:lo,h:sh}; }
  function updateSizes(){ ov.querySelectorAll('.kbz-dev').forEach(function(b){ var d=dimsOf(b), sz=b.querySelector('.sz'); if(sz) sz.textContent=d.w+' × '+d.h; }); }
  function applyDev(){ if(!cur)return; var d=dimsOf(cur); frame.style.width=d.w+'px'; frame.style.height=d.h+'px'; device.style.transform='scale(1)'; var aw=wrap.clientWidth-24, ah=wrap.clientHeight-24, dw=device.offsetWidth, dh=device.offsetHeight, s=Math.min(aw/dw,ah/dh,1); if(!(s>0))s=1; device.style.transform='scale('+s+')'; meta.innerHTML='<b>'+_esc(cur.dataset.n)+'</b> · '+d.w+' × '+d.h+' · 전체화면(최대화) 기준'; try{ var cw=frame.contentWindow; if(cw) setTimeout(function(){ try{ if(cw._fitKiosk)cw._fitKiosk(); else cw.dispatchEvent(new Event('resize')); }catch(_){} },90); }catch(_){} }
  function setOrient(o){ if(ORIENT!==o){ ORIENT=o; loadSrc(); } ov.querySelectorAll('.kbz-ornt button').forEach(function(x){ x.classList.toggle('on', x.dataset.o===o); }); updateSizes(); applyDev(); }
  function setType(t){ if(TYPE!==t){ TYPE=t; loadSrc(); } ov.querySelectorAll('.kbz-type button').forEach(function(x){ x.classList.toggle('on', x.dataset.t===t); }); applyDev(); }
  ov.querySelectorAll('.kbz-ornt button').forEach(function(b){ b.addEventListener('click',function(){ setOrient(b.dataset.o); }); });
  if(typeToggle) ov.querySelectorAll('.kbz-type button').forEach(function(b){ b.addEventListener('click',function(){ setType(b.dataset.t); }); });
  ov.querySelectorAll('.kbz-dev').forEach(function(b){ b.addEventListener('click',function(){ ov.querySelectorAll('.kbz-dev').forEach(function(x){x.classList.remove('on');}); b.classList.add('on'); cur=b; if(b.dataset.ph==='1'){ setOrient('portrait'); } else { applyDev(); } }); });
  frame.addEventListener('load',function(){ try{ if(frame.contentWindow._fitKiosk)frame.contentWindow._fitKiosk(); else frame.contentWindow.dispatchEvent(new Event('resize')); }catch(_){} setTimeout(applyDev,30); });
  function onResize(){ applyDev(); }
  function close(){ try{document.removeEventListener('keydown',onKey,true);}catch(_){} try{window.removeEventListener('resize',onResize);}catch(_){} closeModalGracefully(ov); }
  function onKey(e){ if(e.key==='Escape'){ e.preventDefault(); close(); } }
  ov.addEventListener('mousedown',function(e){ if(e.target===ov) close(); });   /* 딤 배경 클릭 시 닫기 (닫기 버튼 제거 — 배경 클릭/ESC 로 닫음, 사용자 요청 2026-06-15) */
  document.addEventListener('keydown',onKey,true);
